// AI generated by: Claude Code / claude-opus-5-5
// Prompt: "Changes view for the grids"
// Changes: Tests of the Changes view grids – the precedence table, the LL table and the Empty/First/Follow/Predict
//          tables of a draft, with the cells that adopting the draft would change carrying the project's and the
//          draft's value (what the grid shows and announces).

import { describe, expect, it } from 'vitest'
import { draftChanges } from './changes'
import { changeGrids } from './changeGrids'
import { cellDetail } from './tableModel'
import type { Parts } from './parts'

const CONFLICTING = 'E -> id\nE -> id + E'
const FIXED = 'E -> id R\nR -> + E\nR -> eps'

function project(): Parts {
  return {
    definition: { nonterminals: 'E', terminals: 'id\n+', start: 'E' },
    grammarRules: CONFLICTING,
    precTable: { terminals: ['+', 'id'], cells: { 'id\u0001+': '>', '+\u0001id': '<' } },
    reductionRules: 'E -> E + E\nE -> id',
  }
}

const fixedDefinition = { nonterminals: 'E\nR', terminals: 'id\n+', start: 'E' }

const gridsFor = (patch: Partial<Parts>) => {
  const p = project()
  const draft = { ...p, ...patch }
  return changeGrids(draft, draftChanges({ draft, project: p }))
}

/** The grid as text rows (header first), changed cells as "old→new". */
const text = (g: { header: string[]; rows: { head: string; cells: { text: string }[] }[] }) => [g.header, ...g.rows.map((r) => [r.head, ...r.cells.map((c) => c.text)])]

describe('precedence table changes', () => {
  it('a changed relation shows the project’s and the draft’s value; set ↔ empty included', () => {
    const g = gridsFor({ precTable: { terminals: ['+', 'id'], cells: { 'id\u0001+': '<', 'id\u0001$': '>' } } })
    expect(text(g.precTable)).toEqual([
      ['Zásobník \\ vstup', '+', 'id', '$'],
      ['+', '', '<→∅', ''],
      ['id', '>→<', '', '∅→>'],
      ['$', '', '', ''],
    ])
    expect(g.precTable.rows[1].cells[0].change).toEqual({ old: '>', new: '<' })
    expect(g.precTable.rows[0].cells[0].change).toBeNull()
  })

  it('the cell detail announces the old and the new relation', () => {
    const g = gridsFor({ precTable: { terminals: ['+', 'id'], cells: { 'id\u0001+': '<' } } })
    expect(cellDetail(g.precTable, 1, 0)).toBe('[id, +] → zmenené; v projekte >; v návrhu <')
    expect(cellDetail(g.precTable, 0, 1)).toBe('[+, id] → zmenené; v projekte <; v návrhu prázdne')
    expect(cellDetail(g.precTable, 0, 0)).toBe('[+, +] → prázdna bunka (syntaktická chyba)')
  })

  it('added and removed terminals are marked; a removed terminal keeps its row and column', () => {
    const g = gridsFor({ precTable: { terminals: ['+', '*'], cells: { '+\u0001*': '<' } } })
    expect(g.precTable.header).toEqual(['Zásobník \\ vstup', '+', '*', 'id', '$'])
    expect(g.precTable.added).toEqual(['*'])
    expect(g.precTable.removed).toEqual(['id'])
    expect(text(g.precTable)[3]).toEqual(['id', '>→∅', '', '', ''])
  })
})

describe('LL table changes', () => {
  it('the draft’s LL table with the cells whose rules differ as "old→new"', () => {
    const g = gridsFor({ grammarRules: FIXED, definition: fixedDefinition })
    expect(text(g.llTable)).toEqual([
      ['', 'id', '+', '$'],
      ['E', '1,2→1', '', ''],
      ['R', '', '∅→2', '∅→3'],
    ])
    expect(g.llTable.added).toEqual(['R'])
  })

  it('a resolved conflict is called out in the cell detail with both sides’ rules', () => {
    const g = gridsFor({ grammarRules: FIXED, definition: fixedDefinition })
    expect(cellDetail(g.llTable, 0, 0)).toBe('[E, id] → vyriešený konflikt; v projekte 1: E → id, 2: E → id + E; v návrhu 1: E → id R')
    expect(cellDetail(g.llTable, 1, 1)).toBe('[R, +] → zmenené; v projekte prázdne; v návrhu 2: R → + E')
  })

  it('a new conflict is flagged as a conflict and called out', () => {
    const g = gridsFor({ grammarRules: CONFLICTING + '\nE -> + E', definition: project().definition })
    const before = changeGrids(project(), draftChanges({ draft: project(), project: project() }))
    expect(before.llTable.rows[0].cells[0]).toMatchObject({ text: '1, 2', conflict: true, change: null })
    expect(g.llTable.rows[0].cells[1]).toMatchObject({ text: '∅→3', conflict: false })

    const fixed = { ...project(), grammarRules: FIXED, definition: fixedDefinition }
    const draft = { ...fixed, grammarRules: FIXED + '\nE -> id' }
    const broken = changeGrids(draft, draftChanges({ draft, project: fixed }))
    expect(broken.llTable.rows[0].cells[0]).toMatchObject({ text: '1→1,4', conflict: true })
    expect(cellDetail(broken.llTable, 0, 0)).toBe('[E, id] → konflikt: nový konflikt; v projekte 1: E → id R; v návrhu 1: E → id R, 4: E → id')
  })

  it('a nonterminal only the project has keeps its row with the old rules', () => {
    const fixed = { ...project(), grammarRules: FIXED, definition: fixedDefinition }
    const g = changeGrids(project(), draftChanges({ draft: project(), project: fixed }))
    expect(text(g.llTable)).toEqual([
      ['', 'id', '+', '$'],
      ['E', '1→1,2', '', ''],
      ['R', '', '2→∅', '3→∅'],
    ])
    expect(g.llTable.removed).toEqual(['R'])
  })
})

describe('Empty, First, Follow and Predict changes', () => {
  it('changed sets show the project’s and the draft’s value; unchanged ones the draft’s', () => {
    const g = gridsFor({ grammarRules: FIXED, definition: fixedDefinition })
    expect(text(g.sets)).toEqual([
      ['Neterminál', 'Empty', 'First', 'Follow'],
      ['E', '∅', '{ id }', '{ $ }'],
      ['R', '∅→{ ε }', '∅→{ + }', '∅→{ $ }'],
    ])
    expect(g.sets.added).toEqual(['R'])
    expect(cellDetail(g.sets, 1, 1)).toBe('[R, First] → zmenené; v projekte prázdne; v návrhu { + }')
  })

  it('predict rows whose rule text or Predict set changed', () => {
    const g = gridsFor({ grammarRules: FIXED, definition: fixedDefinition })
    expect(text(g.predict)).toEqual([
      ['#', 'Pravidlo', 'Predict'],
      ['1', 'E → id→E → id R', '{ id }'],
      ['2', 'E → id + E→R → + E', '{ id }→{ + }'],
      ['3', '∅→R → ε', '∅→{ $ }'],
    ])
  })

  // AI generated by: Claude Code / claude-opus-5-5
  // Prompt: "yes please fix it" (the LL Changes view flagged every cell whose rule was only renumbered)
  // Changes: An inserted rule is the only added predict row; renumbered rules are unchanged.
  it('an inserted rule is the only predict change; renumbered rules show the draft’s numbers unchanged', () => {
    const g = gridsFor({ grammarRules: 'E -> id\nE -> + E\nE -> id + E' })
    expect(text(g.predict)).toEqual([
      ['#', 'Pravidlo', 'Predict'],
      ['1', 'E → id', '{ id }'],
      ['2', '∅→E → + E', '∅→{ + }'],
      ['3', 'E → id + E', '{ id }'],
    ])
    expect(g.predict.added).toEqual(['2'])
    expect(g.predict.removed).toEqual([])
  })

  it('a part without changes has no changed cell anywhere', () => {
    const g = gridsFor({})
    const all = [g.precTable, g.llTable, g.sets, g.predict].flatMap((t) => t.rows.flatMap((r) => r.cells))
    expect(all.length).toBeGreaterThan(0)
    expect(all.filter((c) => c.change)).toEqual([])
  })
})
